package providers

// Code generated from the upstream 9router provider registry. DO NOT EDIT.
//
// This is the single source of truth for provider display metadata: category,
// auth type, icon, colour, and the per-provider feature flags the dashboard
// renders. The Svelte dashboard reads it through the API, so a provider added
// here appears in the UI without a second edit.

// ProviderMeta is the display metadata for one provider.
type ProviderMeta struct {
	ID          string   `json:"id"`
	Name        string   `json:"name"`
	Alias       string   `json:"alias,omitempty"`
	Category    Category `json:"category"`
	AuthType    string   `json:"authType"`
	Color       string   `json:"color,omitempty"`
	Icon        string   `json:"icon,omitempty"`
	Priority    int      `json:"priority,omitempty"`
	Description string   `json:"description,omitempty"`

	// Optional per-provider flags, all with a UI consumer.
	NoAuth             bool     `json:"noAuth,omitempty"`
	Hidden             bool     `json:"hidden,omitempty"`
	Usage              bool     `json:"usage,omitempty"`
	AuthModes          []string `json:"authModes,omitempty"`
	AuthHint           string   `json:"authHint,omitempty"`
	CredentialForm     string   `json:"credentialForm,omitempty"`
	APIKeyOptionalWith string   `json:"apiKeyOptionalWith,omitempty"`
	PassthroughModels  bool     `json:"passthroughModels,omitempty"`
	MediaPriority      int      `json:"mediaPriority,omitempty"`
	ServiceKinds       []string `json:"serviceKinds,omitempty"`
	HiddenKinds        []string `json:"hiddenKinds,omitempty"`
	Website            string   `json:"website,omitempty"`
	Notice             *Notice  `json:"notice,omitempty"`
	ModelsFetcher      *Fetcher `json:"modelsFetcher,omitempty"`
	Regions            []Region `json:"regions,omitempty"`
	DefaultRegion      string   `json:"defaultRegion,omitempty"`
}

// Fetcher is the upstream registry modelsFetcher: a public catalog the
// dashboard offers as "Suggested free models".
type Fetcher struct {
	URL  string `json:"url"`
	Type string `json:"type"`
}

// Notice is the upstream display.notice block.

type Notice struct {
	Text      string `json:"text,omitempty"`
	APIKeyURL string `json:"apiKeyUrl,omitempty"`
	SignupURL string `json:"signupUrl,omitempty"`
}

// Region is one upstream regions[] entry.
type Region struct {
	ID    string `json:"id"`
	Label string `json:"label"`
}

